F_DECODE=formula('D=Σ_{j=0}^{l−1} b_j 2^j; x=x_min+(x_max−x_min)D/(2^l−1)',{'D':'unsigned decoded integer','b_j':'bit at binary place j, with j=0 the rightmost bit','j':'binary-place index','l':'number of bits','x':'decoded design variable','x_min,x_max':'lower and upper bounds'},{'D,b_j,j,l':'dimensionless','x,x_min,x_max':'same declared design-variable units'},['l is a positive integer; each bit is 0 or 1; x_min<x_max.'])
F_ROULETTE=formula('p_i=f_i/Σ_j f_j; E[n_i]=N p_i',{'p_i':'probability of selecting candidate i on one draw','f_i':'nonnegative selection fitness of candidate i','f_j':'fitness of candidate j','i,j':'candidate indices','N':'number of independent draws','n_i':'number of copies of candidate i'},{'p_i,N,n_i,i,j':'dimensionless','f_i,f_j':'common fitness units'},['Σ_j f_j>0; draws with replacement for the expected-copy statement.'])
F_RANK=formula('p_i=R_i/Σ_{j=1}^{N} R_j',{'p_i':'selection probability of candidate i','R_i,R_j':'positive ranks of candidates i and j','N':'population size','i,j':'candidate indices'},{'p_i,R_i,R_j,N,i,j':'dimensionless'},['No ties in the stated example; lowest fitness rank is 1; largest rank is N.'])
F_BINOM=formula('E[K]=n p; P(K=k)=C(n,k)p^k(1−p)^(n−k)',{'K':'number of flipped bits','n':'number of independently tested bits','p':'common per-bit mutation probability','k':'specified integer count','C(n,k)':'binomial coefficient n choose k'},{'K,n,p,k,C(n,k)':'dimensionless'},['Independent Bernoulli trials; n is a nonnegative integer; 0≤p≤1; 0≤k≤n.'])
F_SBX=formula('α=(2r)^(1/(q+1)) for r≤1/2; α=[1/(2(1−r))]^(1/(q+1)) for r>1/2; C_±=(P_1+P_2±α|P_2−P_1|)/2',{'α':'nonnegative sampled child-to-parent separation ratio','r':'uniform random variate in (0,1)','q':'distribution index','P_1,P_2':'scalar parent values','C_−,C_+':'lower and upper child values'},{'α,r,q':'dimensionless','P_1,P_2,C_−,C_+':'common design-variable units'},['q≥0; unbounded SBX; no decision-bound clipping; use unchanged parents for the equal-parent limiting case.'])
F_DENS=formula('h(α)=0.5(q+1)α^q for 0≤α≤1; h(α)=0.5(q+1)α^(−q−2) for α>1',{'h':'probability density of spread ratio','α':'nonnegative child-to-parent separation ratio','q':'distribution index'},{'h,α,q':'dimensionless'},['q≥0; unbounded scalar SBX model.'])
F_POLY=formula('δ̄=(2r)^(1/(q+1))−1 if r<0.5; δ̄=1−[2(1−r)]^(1/(q+1)) otherwise; P_mut=P_org+δ̄ δ_max',{'δ̄':'signed normalized perturbation','r':'random variate in [0,1]','q':'distribution index','P_mut':'mutated scalar variable','P_org':'original scalar variable','δ_max':'maximum absolute perturbation'},{'δ̄,r,q':'dimensionless','P_mut,P_org,δ_max':'common design-variable units'},['q≥0; δ_max≥0; the displayed unbounded formula does not itself repair constraints.'])
F_PEN=formula('P=C Σ_{k=1}^{m} φ_k(X)^2; F=f+P (minimize) or F=f−P (maximize)',{'P':'nonnegative penalty','C':'nonnegative penalty coefficient','φ_k(X)':'nonnegative violation of constraint k, zero when satisfied','X':'candidate design vector','m':'number of constraints','k':'constraint index','f':'raw objective','F':'penalized objective'},{'P,f,F':'common objective units','φ_k':'normalized dimensionless violation in the stated examples','C':'objective units','m,k':'dimensionless','X':'declared design-variable units'},['Violations are normalized consistently; choose the sign that makes violation less attractive.'])
